@torch.jit.script
def _residual_gru_layer(inputs: torch.Tensor, hidden: torch.Tensor,
                        weight_ih: torch.Tensor, weight_hh: torch.Tensor,
                        bias_ih: torch.Tensor, bias_hh: torch.Tensor):
    # Precompute input projections while retaining sequential recurrent gates.
    projected = torch.nn.functional.linear(inputs, weight_ih, bias_ih)
    outputs = torch.jit.annotate(list[torch.Tensor], [])
    for t in range(inputs.size(1)):
        input_r, input_z, input_n = projected[:, t].chunk(3, dim=-1)
        hidden_r, hidden_z, hidden_n = torch.nn.functional.linear(
            hidden, weight_hh, bias_hh
        ).chunk(3, dim=-1)
        reset = torch.sigmoid(input_r + hidden_r)
        update = torch.sigmoid(input_z + hidden_z)
        candidate = torch.tanh(input_n + reset * hidden_n)
        gru_hidden = candidate + update * (hidden - candidate)
        hidden = 0.1 * hidden + 0.9 * gru_hidden
        outputs.append(hidden)
    return torch.stack(outputs, dim=1), hidden


class ResidualGRU(nn.GRU):
    def forward(self, inputs: torch.Tensor, hx=None):
        if hx is None:
            hx = inputs.new_zeros(self.num_layers, inputs.size(0), self.hidden_size)
        out = inputs
        final_states = []
        for layer in range(self.num_layers):
            out, hidden = _residual_gru_layer(
                out, hx[layer],
                getattr(self, f"weight_ih_l{layer}"),
                getattr(self, f"weight_hh_l{layer}"),
                getattr(self, f"bias_ih_l{layer}"),
                getattr(self, f"bias_hh_l{layer}"),
            )
            final_states.append(hidden)
            if layer + 1 < self.num_layers and self.dropout > 0.0:
                out = torch.nn.functional.dropout(
                    out, p=self.dropout, training=self.training
                )
        return out, torch.stack(final_states, dim=0)


